// Label returns the German label of a sport/sub-sport combination.
func Label(sport, subSport string) string {
	if l, ok := labels[sport+"/"+subSport]; ok {
		return l
	}
	if l, ok := labels[sport]; ok {
		return l
	}
	if sport == "" {
		return "Unbekannt"
	}
	return sport
}

// Icon returns the emoji of the activity's category.
func Icon(sport, subSport string) string { return CategoryOf(sport, subSport).Icon }
